    inner_function().map_err(|e| SecurityError::DependencyFailed {
        dependency: "inner_function".to_string(),
        underlying_error: e.to_string(),
        context: create_security_context(),
        metadata: SecurityMetadata::default(),
        ai_remediation: None,
    })?;
    // ...
}
